import mezz.jei.api.runtime.IIngredientManager;
import mezz.jei.api.runtime.IJeiRuntime;
import net.minecraft.client.Minecraft;
import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.eventbus.api.Event;
import org.jetbrains.annotations.NotNull;

@JeiPlugin
public class CreateConnectedJEI
implements IModPlugin {
    private static final ResourceLocation ID = CreateConnected.asResource("jei_plugin");
    public static IIngredientManager MANAGER;

    @NotNull
    public ResourceLocation getPluginUid() {
        return ID;
    }

    public void onRuntimeAvailable(IJeiRuntime jeiRuntime) {
        MANAGER = jeiRuntime.getIngredientManager();
    }

    public static void refreshItemList() {
        if (MANAGER != null && Minecraft.m_91087_().f_91073_ != null) {
            MinecraftForge.EVENT_BUS.post((Event)new FeatureRefreshEvent.Pre(ID, MANAGER));
            MANAGER.removeIngredientsAtRuntime((IIngredientType)VanillaTypes.ITEM_STACK, (Collection)CCCreativeTabs.ITEMS.stream().map(ItemProviderEntry::asStack).collect(Collectors.toList()));
            MANAGER.addIngredientsAtRuntime((IIngredientType)VanillaTypes.ITEM_STACK, (Collection)CCCreativeTabs.ITEMS.stream().filter(x -> FeatureToggle.isEnabled(x.getId())).map(ItemProviderEntry::asStack).collect(Collectors.toList()));
            MinecraftForge.EVENT_BUS.post((Event)new FeatureRefreshEvent.Post(ID, MANAGER));
        }
    }
}

