package com.hlysine.create_connected.ponder;

import com.simibubi.create.foundation.ponder.CreateSceneBuilder;
import net.createmod.ponder.api.PonderPalette;
import net.createmod.ponder.api.scene.SceneBuilder;
import net.createmod.ponder.api.scene.SceneBuildingUtil;
import net.createmod.ponder.api.scene.Selection;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;

public class InvertedClutchScenes {
    public static void invertedClutch(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("inverted_clutch", "Controlling rotational force using an Inverted Clutch");
        scene.configureBasePlate(0, 0, 5);
        scene.world().showSection(util.select().layer(0), Direction.UP);
        BlockPos leverPos = util.grid().at(3, 1, 0);
        scene.world().showSection(util.select().fromTo(leverPos, leverPos.m_122019_()), Direction.UP);
        BlockPos gaugePos = util.grid().at(0, 1, 2);
        Selection gauge = util.select().position(gaugePos);
        scene.world().showSection(gauge, Direction.UP);
        scene.idle(5);
        scene.world().showSection(util.select().position(5, 1, 2), Direction.DOWN);
        scene.idle(10);
        for (int i = 4; i >= 1; --i) {
            scene.idle(5);
            scene.world().showSection(util.select().position(i, 1, 2), Direction.DOWN);
        }
        BlockPos clutch = util.grid().at(3, 1, 2);
        scene.effects().indicateSuccess(gaugePos);
        scene.idle(10);
        scene.overlay().showText(50).text("Inverted Clutches will not relay rotation...").placeNearTarget().pointAt(util.vector().topOf(clutch));
        scene.idle(60);
        scene.world().toggleRedstonePower(util.select().fromTo(leverPos, leverPos.m_122020_(2)));
        scene.effects().indicateRedstone(leverPos);
        scene.world().setKineticSpeed(util.select().fromTo(0, 1, 2, 2, 1, 2), 32.0f);
        scene.idle(10);
        scene.idle(10);
        scene.overlay().showText(50).colored(PonderPalette.RED).text("...unless they are powered by Redstone").attachKeyFrame().placeNearTarget().pointAt(util.vector().topOf(clutch));
        scene.idle(70);
        scene.markAsFinished();
    }
}

