        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("linked_transmitter", "Using Linked Transmitters");
        scene.configureBasePlate(0, 0, 5);
        BlockPos button = util.grid().at(1, 1, 1);
        BlockPos lever = util.grid().at(2, 1, 1);
        BlockPos analogLever = util.grid().at(3, 1, 1);
        BlockPos linkLeft = util.grid().at(3, 2, 2);
        BlockPos linkRight = util.grid().at(1, 2, 2);
        Selection buttonSelect = util.select().position(button);
        Selection analogLeverSelect = util.select().position(analogLever);
        Selection leverSelect = util.select().position(lever);
        Selection linkLeftSelect = util.select().position(linkLeft);
        Selection linkRightSelect = util.select().position(linkRight);
        Vec3 transmitVec = util.vector().blockSurface(lever, Direction.DOWN).m_82520_(0.0, 0.1875, 0.0);
        Vec3 linkLeftVec = util.vector().blockSurface(linkLeft, Direction.SOUTH).m_82520_(0.0, 0.0, -0.1875);
        Vec3 linkRightVec = util.vector().blockSurface(linkRight, Direction.SOUTH).m_82520_(0.0, 0.0, -0.1875);
        scene.world().showSection(util.select().layer(0), Direction.UP);
        scene.idle(5);
        scene.world().showSection(util.select().fromTo(4, 1, 3, 0, 2, 3), Direction.DOWN);
        scene.idle(10);
        scene.world().showSection(leverSelect, Direction.DOWN);
        scene.idle(5);
        scene.world().showSection(util.select().position(linkRight), Direction.DOWN);
        scene.idle(5);
        scene.world().showSection(util.select().position(linkLeft), Direction.DOWN);
        scene.idle(10);
        scene.overlay().showControls(transmitVec, Pointing.UP, 40).rightClick().withItem(new ItemStack(CCItems.LINKED_TRANSMITTER));
        scene.idle(10);
        scene.world().modifyBlock(lever, s -> (BlockState)((BlockState)((BlockState)CCBlocks.LINKED_LEVER.getDefaultState().m_61124_((Property)BlockStateProperties.f_61376_, (Comparable)((AttachFace)s.m_61143_((Property)BlockStateProperties.f_61376_)))).m_61124_((Property)BlockStateProperties.f_61374_, (Comparable)((Direction)s.m_61143_((Property)BlockStateProperties.f_61374_)))).m_61124_((Property)BlockStateProperties.f_61448_, (Comparable)((Boolean)s.m_61143_((Property)BlockStateProperties.f_61448_))), true);
        scene.idle(10);
